INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66102705', 66102705, 'analyze_legacy', 'Kementerian Agama', 'central', 'KANTOR KEMENTERIAN AGAMA KABUPATEN KUTAI TIMUR 635419', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'E-Purchasing', 'Kalimantan Timur, Kutai Timur (Kab.)', 117040000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Alat Tulis Kantor KUA Kombeng ( 1, THN, @ 11704000 ); 2. Alat Tulis Kantor KUA Karangan ( 1, THN, @ 3192000 ); 3. Alat Tulis Kantor KUA Batu Ampar ( 1, THN, @ 8512000 ); 4. Alat Tulis Kantor KUA Long Masengat ( 1, THN, @ 4256000 ); 5. Alat Tulis Kantor KUA Muara Wahau ( 1, THN, @ 6384000 ); 6. Alat Tulis Kantor KUA Sangkulirang ( 1, THN, @ 4256000 ); 7. Alat Tulis Kantor KUA Busang ( 1, THN, @ 7448000 ); 8. Alat Tulis Kantor KUA Muara Ancalong ( 1, THN, @ 6384000 ); 9. Alat Tulis Kantor KUA Kaliorang ( 1, THN, @ 5320000 ); 10. Alat Tulis Kantor KUA Teluk Pandan ( 1, THN, @ 7448000 ); 11. Alat Tulis Kantor KUA Rantau Pulung ( 1, THN, @ 3192000 ); 12. Alat Tulis Kantor KUA Kaubun ( 1, THN, @ 3192000 ); 13. Alat Tulis Kantor KUA Sangatta Utara ( 1, THN, @ 15960000 ); 14. Alat Tulis Kantor KUA Sandaran ( 1, THN, @ 4256000 ); 15. Alat Tulis Kantor KUA Sangatta Selatan ( 1, THN, @ 7448000 ); 16. Alat Tulis Kantor KUA Telen ( 1, THN, @ 6384000 ); 17. Alat Tulis Kantor KUA Bengalon ( 1, THN, @ 4256000 ); 18. Alat Tulis Kantor KUA Muara Bengkal ( 1, THN, @ 7448000 );', 'Pengadaan Alat Tulis Kantor (ATK) untuk masing-masing Kantor Urusan Agama (KUA) dilaksanakan dalam bentuk paket kebutuhan operasional selama 1 (satu) tahun anggaran yang mencakup penyediaan perlengkapan administrasi dan pelayanan, antara lain kertas HVS A4 dan F4, tinta printer sesuai spesifikasi perangkat yang digunakan, map dan ordner arsip, buku agenda dan buku tulis, alat tulis seperti bolpoin, pensil, dan spidol, stapler dan isi staples, paper clip, lakban, lem kertas, sheet protector, serta perlengkapan pendukung administrasi lainnya. Seluruh barang yang disediakan harus dalam kondisi baru, berkualitas baik, berfungsi optimal, serta sesuai standar kebutuhan perkantoran, dengan spesifikasi teknis yang bersifat umum dan tidak mengarah pada merek tertentu kecuali untuk barang yang menyesuaikan kompatibilitas perangkat, dan volume kebutuhan disesuaikan dengan pagu masing-masing KUA dalam periode 1 (satu) tahun anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 610736);
