INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62540123', 62540123, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Bangka Belitung', 'Satpam Pihak ke-3', 'Jasa Lainnya', 'E-Purchasing', 'Kep. Bangka Belitung, Pangkal Pinang (Kota)', 208000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 26, keg, @ 8000000 )', 'Ruang lingkup kegiatan pengadaan jasa pengamanan Satpam Pihak ke-3 meliputi: 1. Penyediaan 2 (dua) orang tenaga satpam dari pihak ketiga. 2. Pelaksanaan tugas pengamanan kantor dengan sistem kerja yang ditetapkan penyedia. 3. Pengamanan aset, dokumen, pegawai, dan tamu kantor. 4. Pengawasan keluar-masuk orang dan kendaraan. 5. Penanganan gangguan keamanan dan kondisi darurat. Spesifikasi Teknis: 1. Persyaratan Personel • Jumlah personel: 2 (dua) orang satpam • Status: Tenaga kerja dari penyedia jasa pihak ketiga • Warga Negara Indonesia • Usia minimal 20 tahun dan maksimal 45 tahun • Pendidikan minimal SMA/sederajat • Memiliki Sertifikat Gada Pratama yang masih berlaku • Sehat jasmani dan rohani • Berkelakuan baik (SKCK aktif) 2. Tugas dan Tanggung Jawab 1. Menjaga keamanan dan ketertiban kantor 2. Mengawasi keluar masuk pegawai dan tamu 3. Mengamankan aset, dokumen, dan fasilitas kantor 4. Melakukan patroli rutin di area kantor 5. Menangani kondisi darurat (kebakaran, gangguan keamanan) 6. Membuat laporan harian dan insidentil 3. Perlengkapan Satpam (disediakan penyedia) • Seragam dinas lengkap • Sepatu dinas • ID Card • Alat komunikasi (HT/HP) • Buku mutasi dan buku tamu Skema Jam Kerja: Dengan 2 (dua) orang satpam dari pihak ketiga, dan 2 (dua) orang satpam dari Kemendukbangga/BKKBN Perwakilan BKKKBN Provinsi Kepulauan Bangka Belitung pola kerja yang diterapkan sebagai berikut : No Shift Tugas Jam Tugas 1 Pagi 07.30 – 15.30 WIB 2 Sore 15.30 – 23.30 WIB 3 Malam 23.30 – 07.30 WIB Sistem overlap jam kerja memastikan: • Kantor selalu terjaga • Tidak ada kekosongan pengamanan • Tetap sesuai prinsip kewajaran jam kerja • Jika dibutuhkan kegiatan di luar jam kerja, pengamanan dilakukan bersifat situasional sesuai permintaan. X. OUTPUT YANG DIHARAPKAN 1. Tersedianya 2 (dua) orang satpam yang bertugas secara berkelanjutan. 2. Terjaminnya keamanan kantor selama masa kontrak. 3. Tersusunnya laporan pelaksanaan pengamanan secara rutin dan insidentil.', 'Sesuai KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 611329);
