INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65162417', 65162417, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Pengelola Data', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 116561676, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '11', 'Ruang lingkup pelaksanaan pekerjaan Tenaga Pengolah Data di Sekretariat Deputi bidang Perencanaan Makro Pembangunan meliputi: 1. Melakukan pengumpulan data dan informasi yang berkaitan dengan perencanaan makro pembangunan dari berbagai sumber internal dan eksternal. 2. Melakukan pengolahan, verifikasi, dan pemutakhiran data untuk menjamin akurasi, konsistensi, dan keterkinian data. 3. Menyusun, mengelola, dan memelihara basis data serta arsip data dan dokumen perencanaan secara sistematis dan tertib. 4. Menyajikan data dan informasi dalam bentuk tabel, grafik, dan bahan pendukung lainnya sesuai kebutuhan analisis dan pelaporan. 5. Mendukung penyusunan laporan, bahan paparan, dan dokumen perencanaan yang memerlukan dukungan data dan informasi. 6. Melaksanakan koordinasi dengan unit kerja terkait dalam rangka penyediaan dan sinkronisasi data. 7. Melaksanakan tugas lain yang diberikan oleh pimpinan sesuai dengan kebutuhan dan ruang lingkup pekerjaan.', 'Sekretaris di lingkup Sekretariat Deputi Bidang Perencanaan Makro Pembangunan memiliki kualifikasi sebagai berikut : 1. Pendidikan minimal SMA/SMK atau sederajat. 2. Memiliki pengalaman kerja di bidang yang relevan minimal 1 tahun. 3. Menguasai penggunaan aplikasi perkantoran (misalnya Microsoft Excel, Word, PowerPoint). 4. Mampu mengelola, mengolah, dan menyajikan data secara sistematis. 5. Memiliki kemampuan komunikasi baik lisan maupun tulisan dengan baik. 6. Teliti, disiplin, bertanggung jawab, dan mampu bekerja secara mandiri maupun dalam tim.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 611900);
