INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62798299', 62798299, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual Penyusunan Kajian Strategi Utilisasi Dan Pendayagunaan Badan Usaha Milik Daerah (BUMD) Dan Barang Milik Daerah (BMD) Direktorat Pemerintahan, Keuangan Daerah, Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99990000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Menyusun kerangka kerja kegiatan, termasuk instrumen, jadwal, dan mekanisme pelaksanaan; 2. Melakukan peninjauan terhadap arah kebijakan penguatan fondasi keuangan daerah dalam dokumen perencanaan pembangunan yaitu RPJPN 2025-20245, RPJMN 2025-2029 dan RKP 2026; 3. Menginventarisasi dan identifikasi data, informasi, serta menyusun telaah regulasi terkait BUMD dan BMD; 4. Melakukan analisis dan identifikasi kondisi kinerja kontribusi BUMD dan BMD dalam APBD; 5. Mengidentifikasi permasalahan struktural dan kelembagaan BUMD dan BMD di daerah; 6. Melakukan pemetaan profil BUMD dan BMD di seluruh provinsi; 7. Membantu tim dalam berkoordinasi di internal Kementerian PPN/Bappenas maupun dengan K/L terkait; serta 8. Menyusun rancangan rekomendasi strategi rekomendasi untuk peningkatan utilisasi dan pendayagunaan BUMD dan aset daerah (BMD) yang berkontribusi terhadap pendapatan daerah.', '1. Merupakan Tenaga Ahli dalam negeri (Dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki pendidikan minimal Strata Satu (S1) di bidang Administrasi Negara/Administrasi Publik yang dibuktikan dengan ijazah dan transkrip nilai; 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak; 5. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan; 6. Memiliki pengalaman bekerja di pemerintahan selama minimal 1 (satu) tahun yang dibuktikan dengan surat kontrak/referensi pekerjaan yang pernah dilakukan; 7. Memiliki kemampuan komunikasi dan koordinasi yang baik, serta mampu bekerja dalam tim. 8. Menguasai pengelolaan dan analisis data/dokumen menggunakan aplikasi perkantoran (Word, Excel, PowerPoint, dan pengarsipan digital) dibuktikan dengan sertifikat/laporan/presentasi formal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 618770);
